const fullNameError = document.getElementById('fullName-error');
const emailError = document.getElementById('email-error');
const phoneError = document.getElementById('phone-error');

const validators = {
  fullName: (value) => {
    if (!value.trim()) {
      return 'Error: Full name is required.';
    }
    if (value.trim().length < 2) {
      return 'Error: Full name must be at least 2 characters.';
    }
    return '';
  },

  email: (value) => {
    if (!value.trim()) {
      return 'Error: Email address is required.';
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
      return 'Error: Enter a valid email like name@example.com.';
    }
    return '';
  },

  phone: (value) => {
    if (!value.trim()) {
      return '';
    }
    const phoneRegex = /^[\d\s\-().+]{7,}$|^(\+\d{1,3})?[\d\s\-().+]{6,}$/;
    if (!phoneRegex.test(value)) {
      return 'Error: Enter a valid phone number like (555) 123-4567.';
    }
    return '';
  },
};

function validateField(input, errorElement, validator) {
  const error = validator(input.value);

  if (error) {
    input.setAttribute('aria-invalid', 'true');
    errorElement.textContent = error;
  } else {
    input.removeAttribute('aria-invalid');
    errorElement.textContent = '';
  }

  return !error;
}

function validateForm() {
  const fullNameValid = validateField(fullNameInput, fullNameError, validators.fullName);
  const emailValid = validateField(emailInput, emailError, validators.email);
  const phoneValid = validateField(phoneInput, phoneError, validators.phone);

  return fullNameValid && emailValid && phoneValid;
}

function focusFirstInvalidField() {
  const invalidFields = [fullNameInput, emailInput, phoneInput].filter(
    (field) => field.getAttribute('aria-invalid') === 'true'
  );

  if (invalidFields.length > 0) {
    invalidFields[0].focus();
  }
}

fullNameInput.addEventListener('blur', () => {
  validateField(fullNameInput, fullNameError, validators.fullName);
});

fullNameInput.addEventListener('input', () => {
  if (fullNameInput.getAttribute('aria-invalid') === 'true') {
    validateField(fullNameInput, fullNameError, validators.fullName);
  }
});

emailInput.addEventListener('blur', () => {
  validateField(emailInput, emailError, validators.email);
});

emailInput.addEventListener('input', () => {
  if (emailInput.getAttribute('aria-invalid') === 'true') {
    validateField(emailInput, emailError, validators.email);
  }
});

phoneInput.addEventListener('blur', () => {
  validateField(phoneInput, phoneError, validators.phone);
});

phoneInput.addEventListener('input', () => {
  if (phoneInput.getAttribute('aria-invalid') === 'true') {
    validateField(phoneInput, phoneError, validators.phone);
  }
});

form.addEventListener('submit', (e) => {
  e.preventDefault();

  successMessage.classList.add('hidden');

  if (validateForm()) {
    successMessage.classList.remove('hidden');
    form.reset();
    fullNameInput.focus();
  } else {
    focusFirstInvalidField();
  }
});
